Object.assign(D.ru,{"sun.eye": "справочник", "sun.title": "защита от солнца", "sun.btn": "как выбрать, нанести и смыть SPF", "sun.lead": "коротко и только то, что подтверждают источники. на изотретиноине кожа чувствительнее к солнцу, поэтому это не «летняя» тема.", "sun.uvT": "УФ-индекс", "sun.uvNo": "актуальный УФ-индекс в артефакте Claude показать нельзя: он не может надёжно обращаться к погодным сервисам. живой индекс появится в отдельном приложении (PWA). пока смотри УФ в приложении погоды.", "sun.uvRule": "при индексе 3 и выше — защищай кожу", "sun.choose": "как выбрать солнцезащитный крем", "sun.choose1": "SPF 30 или выше.", "sun.choose2": "широкий спектр (broad spectrum) — защита и от UVA, и от UVB. в европейской маркировке ищи значок UVA в кружке.", "sun.choose3": "водостойкость указывают как 40 или 80 минут; она нужна, если потеешь или купаешься.", "sun.choose4": "срок после вскрытия — значок открытой баночки с «M» и числом месяцев.", "sun.fit": "как понять, подходит ли средство коже", "sun.fit1": "нанеси на участок размером с монету на внутренней стороне руки или сгибе локтя.", "sun.fit2": "дважды в день, 7–10 дней, в обычном количестве.", "sun.fit3": "покраснение, зуд или отёк — смой, больше не используй; если реакция сильная и не проходит — к дерматологу.", "sun.fit4": "если непонятно, на какой ингредиент реакция, дерматолог может помочь найти причину. отмечай результат в косметичке.", "sun.forms": "стик, флюид или крем: в чём разница", "sun.forms1": "защита зависит не от формы, а от SPF, широкого спектра и того, сколько средства ты нанесла.", "sun.forms2": "крем или флюид — основной формат; стик и спрей AAD советует как дополнение, а не замену.", "sun.forms3": "стик — дополнение для небольших зон (под глазами, тыльная сторона рук): по 4 прохода туда-обратно и растереть.", "sun.forms4": "спрей на лицо не распыляют: брызни на ладони и нанеси. не вдыхай и держи подальше от огня.", "sun.apply": "как наносить и обновлять SPF", "sun.apply1": "лицо — около чайной ложки (длина указательного и среднего пальцев), всё тело — около 6–8 чайных ложек.", "sun.apply2": "за 15–30 минут до выхода.", "sun.apply3": "обновлять каждые 2 часа на улице и сразу после купания, пота или вытирания полотенцем.", "sun.apply4": "часто забывают уши, шею, линию роста волос, тыльную сторону рук; на губы — бальзам с SPF 30+.", "sun.apply5": "с 11 до 15 — по возможности тень, одежда, головной убор и очки.", "sun.remove": "как смывать солнцезащитные средства", "sun.remove1": "обычно хватает одного мягкого очищающего средства; двойное очищение нужно в основном при макияже или водостойком SPF.", "sun.remove2": "если двойное: сначала средство на масляной основе, затем мягкое на водной. одно масло без второго этапа может провоцировать высыпания у склонной к акне кожи.", "sun.remove3": "тёплая, не горячая вода; при сухой и чувствительной коже — кремовые средства без отдушки, а не пенки.", "sun.remove4": "чрезмерное умывание сушит и раздражает кожу — на курсе это особенно заметно.", "sun.iso": "что учитывать на курсе изотретиноина", "sun.iso1": "препарат повышает чувствительность к солнцу: SPF 30+, одежда и очки, никакого загара и солярия.", "sun.iso2": "воск, лазер и дермабразия — не во время курса и не раньше чем через 6 месяцев после.", "sun.iso3": "сухость глаз может мешать контактным линзам; солнцезащитные очки входят в рекомендованную защиту.", "sun.iso4": "если после солнца появились пузыри, сильное покраснение или сыпь — это повод связаться с врачом, а не просто сменить крем.", "sun.mine": "средства с SPF в косметичке", "sun.ver": "состав проверен", "sun.unver": "состав не проверен", "sun.mineNote": "приложение не советует конкретное средство, пока не проверен точный продукт (название, версия, состав). проверка составов — отдельный этап.", "sun.mineNone": "в косметичке нет средств с SPF в наличии.", "sun.foot": "это справка, а не назначение. при реакции на средство или солнце — к дерматологу."});
Object.assign(D.uk,{"sun.eye": "довідник", "sun.title": "захист від сонця", "sun.btn": "як обрати, нанести й змити SPF", "sun.lead": "коротко й лише те, що підтверджують джерела. на ізотретиноїні шкіра чутливіша до сонця, тож це не «літня» тема.", "sun.uvT": "УФ-індекс", "sun.uvNo": "актуальний УФ-індекс в артефакті Claude показати не можна: він не може надійно звертатися до погодних сервісів. живий індекс зʼявиться в окремому застосунку (PWA). поки дивись УФ у застосунку погоди.", "sun.uvRule": "за індексу 3 і вище — захищай шкіру", "sun.choose": "як обрати сонцезахисний крем", "sun.choose1": "SPF 30 або вище.", "sun.choose2": "широкий спектр (broad spectrum) — захист і від UVA, і від UVB. в європейському маркуванні шукай значок UVA в колі.", "sun.choose3": "водостійкість вказують як 40 або 80 хвилин; вона потрібна, якщо пітнієш або купаєшся.", "sun.choose4": "термін після відкриття — значок відкритої баночки з «M» і кількістю місяців.", "sun.fit": "як зрозуміти, чи підходить засіб шкірі", "sun.fit1": "нанеси на ділянку розміром з монету на внутрішньому боці руки або згині ліктя.", "sun.fit2": "двічі на день, 7–10 днів, у звичній кількості.", "sun.fit3": "почервоніння, свербіж чи набряк — змий, більше не використовуй; якщо реакція сильна й не минає — до дерматолога.", "sun.fit4": "якщо незрозуміло, на який інгредієнт реакція, дерматолог може допомогти знайти причину. відмічай результат у косметичці.", "sun.forms": "стік, флюїд чи крем: у чому різниця", "sun.forms1": "захист залежить не від форми, а від SPF, широкого спектра й того, скільки засобу ти нанесла.", "sun.forms2": "крем або флюїд — основний формат; стік і спрей AAD радить як доповнення, а не заміну.", "sun.forms3": "стік — доповнення для невеликих зон (під очима, тильний бік рук): по 4 проходи туди-назад і розтерти.", "sun.forms4": "спрей на обличчя не розпилюють: бризни на долоні й нанеси. не вдихай і тримай подалі від вогню.", "sun.apply": "як наносити й оновлювати SPF", "sun.apply1": "обличчя — близько чайної ложки (довжина вказівного й середнього пальців), усе тіло — близько 6–8 чайних ложок.", "sun.apply2": "за 15–30 хвилин до виходу.", "sun.apply3": "оновлювати кожні 2 години на вулиці й одразу після купання, поту чи витирання рушником.", "sun.apply4": "часто забувають вуха, шию, лінію росту волосся, тильний бік рук; на губи — бальзам із SPF 30+.", "sun.apply5": "з 11 до 15 — за можливості тінь, одяг, головний убір та окуляри.", "sun.remove": "як змивати сонцезахисні засоби", "sun.remove1": "зазвичай вистачає одного мʼякого очищувального засобу; подвійне очищення потрібне здебільшого при макіяжі чи водостійкому SPF.", "sun.remove2": "якщо подвійне: спершу засіб на олійній основі, потім мʼякий на водній. сама олія без другого етапу може провокувати висипання у схильної до акне шкіри.", "sun.remove3": "тепла, не гаряча вода; при сухій і чутливій шкірі — кремові засоби без віддушки, а не пінки.", "sun.remove4": "надмірне вмивання сушить і подразнює шкіру — на курсі це особливо помітно.", "sun.iso": "що враховувати на курсі ізотретиноїну", "sun.iso1": "препарат підвищує чутливість до сонця: SPF 30+, одяг і окуляри, жодної засмаги й солярію.", "sun.iso2": "віск, лазер і дермабразія — не під час курсу й не раніше ніж через 6 місяців після.", "sun.iso3": "сухість очей може заважати контактним лінзам; сонцезахисні окуляри входять до рекомендованого захисту.", "sun.iso4": "якщо після сонця зʼявилися пухирі, сильне почервоніння чи висип — це привід звʼязатися з лікарем, а не просто змінити крем.", "sun.mine": "засоби з SPF у косметичці", "sun.ver": "склад перевірено", "sun.unver": "склад не перевірено", "sun.mineNote": "застосунок не радить конкретний засіб, доки не перевірено точний продукт (назва, версія, склад). перевірка складів — окремий етап.", "sun.mineNone": "у косметичці немає засобів із SPF у наявності.", "sun.foot": "це довідка, а не призначення. при реакції на засіб чи сонце — до дерматолога."});
Object.assign(D.en,{"sun.eye": "guide", "sun.title": "sun protection", "sun.btn": "choosing, applying and removing SPF", "sun.lead": "short, and only what the sources support. isotretinoin makes skin more sensitive to sun, so this is not just a summer topic.", "sun.uvT": "UV index", "sun.uvNo": "a live UV index cannot be shown in a Claude artifact: it cannot reliably reach weather services. it will come with the standalone app (PWA). for now, check UV in a weather app.", "sun.uvRule": "at 3 or higher, protect your skin", "sun.choose": "how to choose a sunscreen", "sun.choose1": "SPF 30 or higher.", "sun.choose2": "broad spectrum — protects against both UVA and UVB. on EU labels look for UVA in a circle.", "sun.choose3": "water resistance is labelled 40 or 80 minutes; you need it if you sweat or swim.", "sun.choose4": "shelf life after opening — the open-jar symbol with “M” and a number of months.", "sun.fit": "how to tell if a product suits your skin", "sun.fit1": "apply to a coin-sized spot on the inner arm or the bend of the elbow.", "sun.fit2": "twice a day for 7–10 days, in your usual amount.", "sun.fit3": "redness, itching or swelling — wash it off and stop; if severe and not improving, see a dermatologist.", "sun.fit4": "if you cannot pinpoint the ingredient behind a reaction, a dermatologist can help find it. log the result in your skincare bag.", "sun.forms": "stick, fluid or cream: the difference", "sun.forms1": "protection depends on SPF, broad spectrum and how much you apply — not on the format.", "sun.forms2": "cream or fluid is the main format; AAD advises sticks and sprays as a supplement, not a replacement.", "sun.forms3": "sticks supplement lotions for small areas (under the eyes, backs of hands): 4 back-and-forth passes, then rub in.", "sun.forms4": "never spray on the face: spray into your hands and apply. do not inhale; keep away from flames.", "sun.apply": "how to apply and reapply SPF", "sun.apply1": "face — about a teaspoon (the length of your index and middle fingers); whole body — about 6–8 teaspoons.", "sun.apply2": "15–30 minutes before going out.", "sun.apply3": "reapply every 2 hours outdoors and right after swimming, sweating or towelling.", "sun.apply4": "often missed: ears, neck, hairline, backs of hands; for lips use a balm with SPF 30+.", "sun.apply5": "between 11am and 3pm seek shade where you can, plus clothing, a hat and sunglasses.", "sun.remove": "how to remove sunscreen", "sun.remove1": "one gentle cleanser is usually enough; double cleansing is mostly for makeup or water-resistant SPF.", "sun.remove2": "if you double cleanse: oil-based first, then a gentle water-based cleanser. oil alone can trigger breakouts in acne-prone skin.", "sun.remove3": "lukewarm, not hot water; for dry, sensitive skin choose unscented cream cleansers rather than foams.", "sun.remove4": "over-washing dries and irritates skin — especially noticeable during the course.", "sun.iso": "what to consider on isotretinoin", "sun.iso1": "the medicine increases sun sensitivity: SPF 30+, clothing and sunglasses, no tanning or sunbeds.", "sun.iso2": "no waxing, laser or dermabrasion during the course or for 6 months after.", "sun.iso3": "dry eyes can make contact lenses uncomfortable; sunglasses are part of the recommended protection.", "sun.iso4": "blisters, strong redness or a rash after sun exposure are a reason to contact your doctor, not just to switch creams.", "sun.mine": "SPF products in your bag", "sun.ver": "ingredients verified", "sun.unver": "not verified", "sun.mineNote": "the app does not recommend a specific product until the exact product (name, version, ingredients) is verified. ingredient checks are a separate step.", "sun.mineNone": "no SPF products in stock in your bag.", "sun.foot": "reference only, not a prescription. if your skin reacts to a product or the sun, see a dermatologist."});

