Object.assign(D.ru,{"ocr.btn": "распознать с фото", "ocr.hint": "фото отправится в Claude с твоего аккаунта, при первом использовании появится запрос разрешения. снимок сохранится как оригинал. распознанные строки не сохранятся, пока ты их не проверишь. PDF так не читается — сделай скриншот страницы.", "ocr.type": "этот формат не распознаётся. нужен JPEG, PNG или WebP; PDF можно только прикрепить.", "ocr.wait": "распознаю… обычно до минуты.", "ocr.stop": "остановить", "ocr.eGrant": "распознавание не разрешено или недоступно в этом окне. показатели можно ввести вручную.", "ocr.eRate": "сейчас лимит запросов к Claude. попробуй позже или введи вручную.", "ocr.eImg": "файл не подошёл: слишком большой или повреждён. попробуй другой снимок.", "ocr.eRead": "не удалось надёжно прочитать бланк. введи показатели вручную или сделай более чёткий снимок.", "ocr.eOther": "ошибка распознавания. можно попробовать ещё раз.", "ocr.none": "показатели на фото не найдены.", "ocr.kept": "снимок прикреплён к записи как оригинал.", "ocr.found": {"one": "распознан {n} показатель — он выделен рамкой. сверь название, значение, единицы и референс с бланком, исправь ошибки.", "few": "распознано {n} показателя — они выделены рамкой. сверь название, значение, единицы и референс с бланком, исправь ошибки.", "many": "распознано {n} показателей — они выделены рамкой. сверь название, значение, единицы и референс с бланком, исправь ошибки.", "other": "распознано {n} показателя — они выделены рамкой. сверь каждую строку с бланком."}, "ocr.date": "дата в документе: {d}.", "ocr.lab": "лаборатория в документе: {x}.", "ocr.confirm": "я сверила каждую выделенную строку с бланком. распознавание может ошибаться.", "ocr.needOk": "сначала сверь распознанные строки с бланком и отметь подтверждение (или удали эти строки).", "ocr.src": "распознано с фото, проверено"});
Object.assign(D.uk,{"ocr.btn": "розпізнати з фото", "ocr.hint": "фото надішлеться в Claude з твого акаунта, під час першого використання зʼявиться запит дозволу. знімок збережеться як оригінал. розпізнані рядки не збережуться, доки ти їх не перевіриш. PDF так не читається — зроби скриншот сторінки.", "ocr.type": "цей формат не розпізнається. потрібен JPEG, PNG або WebP; PDF можна лише прикріпити.", "ocr.wait": "розпізнаю… зазвичай до хвилини.", "ocr.stop": "зупинити", "ocr.eGrant": "розпізнавання не дозволено або недоступне в цьому вікні. показники можна ввести вручну.", "ocr.eRate": "зараз ліміт запитів до Claude. спробуй пізніше або введи вручну.", "ocr.eImg": "файл не підійшов: завеликий або пошкоджений. спробуй інший знімок.", "ocr.eRead": "не вдалося надійно прочитати бланк. введи показники вручну або зроби чіткіший знімок.", "ocr.eOther": "помилка розпізнавання. можна спробувати ще раз.", "ocr.none": "показників на фото не знайдено.", "ocr.kept": "знімок прикріплено до запису як оригінал.", "ocr.found": {"one": "розпізнано {n} показник — його виділено рамкою. звір назву, значення, одиниці й референс із бланком, виправ помилки.", "few": "розпізнано {n} показники — їх виділено рамкою. звір назву, значення, одиниці й референс із бланком, виправ помилки.", "many": "розпізнано {n} показників — їх виділено рамкою. звір назву, значення, одиниці й референс із бланком, виправ помилки.", "other": "розпізнано {n} показника — звір кожен рядок із бланком."}, "ocr.date": "дата в документі: {d}.", "ocr.lab": "лабораторія в документі: {x}.", "ocr.confirm": "я звірила кожен виділений рядок із бланком. розпізнавання може помилятися.", "ocr.needOk": "спершу звір розпізнані рядки з бланком і познач підтвердження (або видали ці рядки).", "ocr.src": "розпізнано з фото, перевірено"});
Object.assign(D.en,{"ocr.btn": "read from a photo", "ocr.hint": "the photo is sent to Claude from your account; the first time you will be asked to allow it. the image is kept as the original. recognised rows are not saved until you check them. PDFs cannot be read this way — take a screenshot of the page.", "ocr.type": "this format cannot be read. use JPEG, PNG or WebP; PDFs can only be attached.", "ocr.wait": "reading… usually under a minute.", "ocr.stop": "stop", "ocr.eGrant": "recognition is not allowed or unavailable here. you can enter values manually.", "ocr.eRate": "Claude usage limit reached. try later or enter values manually.", "ocr.eImg": "the file was rejected: too large or unreadable. try another photo.", "ocr.eRead": "could not read the report reliably. enter values manually or take a sharper photo.", "ocr.eOther": "recognition failed. you can try again.", "ocr.none": "no values found in the photo.", "ocr.kept": "the photo is attached to the entry as the original.", "ocr.found": {"one": "{n} value recognised — outlined below. check name, value, unit and reference against the report and fix any errors.", "other": "{n} values recognised — outlined below. check name, value, unit and reference against the report and fix any errors."}, "ocr.date": "date on the report: {d}.", "ocr.lab": "laboratory on the report: {x}.", "ocr.confirm": "I checked every outlined row against the report. recognition can make mistakes.", "ocr.needOk": "first check the recognised rows against the report and tick the confirmation (or delete those rows).", "ocr.src": "read from photo, checked"});

Object.assign(D.ru,{"pv.mismatch": "состав на упаковке отличается", "vst.src": "найден официальный состав — сверь с упаковкой", "vst.sec": "только вторичная база данных — сверь с упаковкой", "vst.todo": "требует проверки: состав не подтверждён", "vr.act": "ключевые компоненты", "vr.has": "есть в составе", "vr.no": "нет в составе", "vr.date": "дата проверки {d}", "vr.ask": "формулы меняются и различаются по странам. сверь список ингредиентов на своей упаковке с источником.", "vr.match": "совпадает", "vr.diff": "отличается", "vr.when": "подтверждено тобой {d}", "vr.reset": "сбросить", "vf.fr": "отдушка / aroma", "vf.eo": "эфирные масла или аллергены отдушки", "vf.alc": "спирт (alcohol)", "vf.acid": "кислоты AHA/BHA", "vf.ret": "ретиноиды", "vf.mo": "минеральное масло", "vf.lan": "ланолин", "vf.col": "красители", "vc.clean": "по составу нет ретиноидов, кислот, отдушки и эфирных масел. это не медицинское разрешение: на курсе кожа чувствительнее, начинай с патч-теста.", "vc.caution": "есть компоненты, которые могут раздражать сухую кожу на курсе (выделены выше). перед регулярным использованием — патч-тест, при раздражении прекратить.", "vc.med": "это не косметика, а средство для слизистой: применять по инструкции производителя.", "vc.unknown": "состав не подтверждён — оценки совместимости нет.", "vn.p01": "без сульфатов и кислот, но содержит масло листьев розмарина (эфирное) и бензиловый спирт — аллерген отдушки. производитель советует патч-тест за 24 часа.", "vn.p02": "в списке ингредиентов отдушки нет, но на странице есть фраза о «менее 1% синтетической отдушки» — сверь с упаковкой. для сухой и чувствительной кожи, утром и вечером.", "vn.p03": "крем с 10% пантенола для поддержки барьера; можно наносить двойным слоем на ночь. при сыпи, покраснении или зуде — прекратить.", "vn.p04": "официальный состав не найден, у крема несколько версий формулы. в версии из базы Skinsort есть экстракт лаванды (аллерген линалоол).", "vn.p05": "для сухой и очень сухой обезвоженной кожи лица. содержит отдушку (parfum) и минеральное масло.", "vn.p06": "на официальной странице нет списка ингредиентов — производитель отсылает к упаковке. назначение: очень сухая, раздражённая, атопичная кожа лица и тела.", "vn.p07": "смываемое масло для душа, без сульфатов, с отдушкой. для лица и тела, 1–2 раза в день.", "vn.p08": "для сухой, раздражённой кожи лица и тела, 1–2 раза в день. не наносить на контур глаз. после вскрытия — 6–12 месяцев.", "vn.p09": "в составе «Alcohol» (во второй половине списка), «Aroma» и красители CI 15985 и CI 15850. производитель: не наносить на повреждённую кожу, при покраснении или зуде прекратить.", "vn.p10": "для сухих, потрескавшихся губ; наносить сколько нужно. после вскрытия — 18 месяцев.", "vn.p11": "100% ланолин без добавок, отдушек и консервантов; по данным производителя подходит для губ. нельзя при аллергии на ланолин.", "vn.p12": "химические (органические) фильтры, SPF 50+ PA++++. наносить последним шагом, обновлять каждые 2–3 часа.", "vn.p13": "на официальной странице только список фильтров и заявления «без отдушки» и «без спирта», полного состава нет. SPF 50+ PA++++.", "vn.p14": "официальную страницу проверить не удалось. существуют версии SPF 25 и SPF 30 — у тебя в списке SPF 30, сверь название и состав с упаковкой.", "vn.p15": "медицинское изделие: без консервантов и фосфатов, совместимо с контактными линзами. после вскрытия — 6 месяцев, хранить не выше 25 °C.", "vn.p16": "для увлажнения сухой слизистой носа. по инструкции взрослым — 2–3 впрыска в каждую ноздрю 4–8 раз в день, курс 2–4 недели. противопоказание — гиперчувствительность к компонентам.", "vn.p17": "гидроколлоидный патч без лечебных компонентов. на официальной странице — версия «Basic», название «Original Fit» не подтверждено. клеить на чистую сухую кожу вместо выдавливания.", "vn.p18": "неизвестны производитель и чистота масла. чтобы проверить, нужна упаковка или ссылка на продукт.", "vn.p19": "по карточке магазина: 4 эфирных масла (чайное дерево, тимьян, эвкалипт, сосна) и фарнезол. для ногтей и кутикулы; на сухой коже вокруг ногтей возможно раздражение. официальный состав не найден.", "vn.p20": "официальный состав не найден, данные из базы Skinsort. есть экстракт куркумы с функцией ароматизатора. пробник."});
Object.assign(D.uk,{"pv.mismatch": "склад на упаковці відрізняється", "vst.src": "знайдено офіційний склад — звір з упаковкою", "vst.sec": "лише вторинна база даних — звір з упаковкою", "vst.todo": "потребує перевірки: склад не підтверджено", "vr.act": "ключові компоненти", "vr.has": "є в складі", "vr.no": "немає в складі", "vr.date": "дата перевірки {d}", "vr.ask": "формули змінюються й різняться за країнами. звір список інгредієнтів на своїй упаковці з джерелом.", "vr.match": "збігається", "vr.diff": "відрізняється", "vr.when": "підтверджено тобою {d}", "vr.reset": "скинути", "vf.fr": "віддушка / aroma", "vf.eo": "ефірні олії або алергени віддушки", "vf.alc": "спирт (alcohol)", "vf.acid": "кислоти AHA/BHA", "vf.ret": "ретиноїди", "vf.mo": "мінеральна олія", "vf.lan": "ланолін", "vf.col": "барвники", "vc.clean": "за складом немає ретиноїдів, кислот, віддушки та ефірних олій. це не медичний дозвіл: на курсі шкіра чутливіша, починай з патч-тесту.", "vc.caution": "є компоненти, що можуть подразнювати суху шкіру на курсі (виділені вище). перед регулярним використанням — патч-тест, при подразненні припинити.", "vc.med": "це не косметика, а засіб для слизової: застосовувати за інструкцією виробника.", "vc.unknown": "склад не підтверджено — оцінки сумісності немає.", "vn.p01": "без сульфатів і кислот, але містить олію листя розмарину (ефірну) та бензиловий спирт — алерген віддушки. виробник радить патч-тест за 24 години.", "vn.p02": "у списку інгредієнтів віддушки немає, але на сторінці є фраза про «менше 1% синтетичної віддушки» — звір з упаковкою. для сухої та чутливої шкіри, вранці й увечері.", "vn.p03": "крем із 10% пантенолу для підтримки барʼєра; можна наносити подвійним шаром на ніч. при висипі, почервонінні чи свербежі — припинити.", "vn.p04": "офіційний склад не знайдено, у крему кілька версій формули. у версії з бази Skinsort є екстракт лаванди (алерген ліналоол).", "vn.p05": "для сухої та дуже сухої зневодненої шкіри обличчя. містить віддушку (parfum) і мінеральну олію.", "vn.p06": "на офіційній сторінці немає списку інгредієнтів — виробник відсилає до упаковки. призначення: дуже суха, подразнена, атопічна шкіра обличчя й тіла.", "vn.p07": "змивна олія для душу, без сульфатів, з віддушкою. для обличчя й тіла, 1–2 рази на день.", "vn.p08": "для сухої, подразненої шкіри обличчя й тіла, 1–2 рази на день. не наносити на контур очей. після відкриття — 6–12 місяців.", "vn.p09": "у складі «Alcohol» (у другій половині списку), «Aroma» та барвники CI 15985 і CI 15850. виробник: не наносити на пошкоджену шкіру, при почервонінні чи свербежі припинити.", "vn.p10": "для сухих, потрісканих губ; наносити скільки потрібно. після відкриття — 18 місяців.", "vn.p11": "100% ланолін без добавок, віддушок і консервантів; за даними виробника підходить для губ. не можна при алергії на ланолін.", "vn.p12": "хімічні (органічні) фільтри, SPF 50+ PA++++. наносити останнім кроком, оновлювати кожні 2–3 години.", "vn.p13": "на офіційній сторінці лише список фільтрів і заяви «без віддушки» та «без спирту», повного складу немає. SPF 50+ PA++++.", "vn.p14": "офіційну сторінку перевірити не вдалося. існують версії SPF 25 і SPF 30 — у тебе в списку SPF 30, звір назву й склад з упаковкою.", "vn.p15": "медичний виріб: без консервантів і фосфатів, сумісний із контактними лінзами. після відкриття — 6 місяців, зберігати не вище 25 °C.", "vn.p16": "для зволоження сухої слизової носа. за інструкцією дорослим — 2–3 впорскування в кожну ніздрю 4–8 разів на день, курс 2–4 тижні. протипоказання — гіперчутливість до компонентів.", "vn.p17": "гідроколоїдний патч без лікувальних компонентів. на офіційній сторінці — версія «Basic», назву «Original Fit» не підтверджено. клеїти на чисту суху шкіру замість видавлювання.", "vn.p18": "невідомі виробник і чистота олії. щоб перевірити, потрібна упаковка або посилання на продукт.", "vn.p19": "за карткою магазину: 4 ефірні олії (чайне дерево, чебрець, евкаліпт, сосна) і фарнезол. для нігтів і кутикули; на сухій шкірі навколо нігтів можливе подразнення. офіційний склад не знайдено.", "vn.p20": "офіційний склад не знайдено, дані з бази Skinsort. є екстракт куркуми з функцією ароматизатора. пробник."});
