const SYM_CATS=['skin','mucosa','head','pain','gi','general','hair','repro','other'];
const symSrc=k=>{const id=symId(k),x=id&&SYMS.find(q=>q[0]===id);return x?x[3]||'':null};
const symUrg=k=>(symSrc(k)||'').includes('u');
const BASE8=['dry_lips','dry_skin','dry_eyes','dry_nose','nosebleed','headache','fatigue','itch_rash'];
const SYM_ORD=SYMS.map(x=>x[0]);
const SYM_IDX={};SYMS.forEach(([id,,al])=>{SYM_IDX[id.replace(/[^a-z]/g,'')]=id;al.forEach(a=>SYM_IDX[a.toLowerCase().replace(/[^a-zа-яёіїєґ]/g,'')]=id)});
const normK=k=>String(k).toLowerCase().replace(/[^a-zа-яёіїєґ]/g,'');
/* полные названия на трёх языках тоже распознаются: свой симптом «головокружение» = каталожный dizziness */
