const symId=k=>SYM_IDX[normK(k)]||null;
const symL=k=>{const id=symId(k);return id?t('sym.'+id):String(k).replace(/_/g,' ')};
const symCat=k=>{const id=symId(k);return id?SYMS.find(x=>x[0]===id)[1]:null};
const symCanon=k=>symId(k)||k;
/* уровень симптома x в записи e с учётом синонимов ключа (старые ключи Lovable, ручные названия) */
function sevOf(e,x){if(!e||!e.severities)return null;const c=symCanon(x);let r=null;for(const[k,v]of Object.entries(e.severities))if(symCanon(k)===c&&!sevIsUnk(v)){const l=sevLvl(v);r=Math.max(r??0,l??1)}return r}
const sevKeyIn=(e,x)=>{if(!e||!e.severities)return null;if(x in e.severities)return x;const c=symCanon(x);return Object.keys(e.severities).find(k=>symCanon(k)===c)||null};
/* один представитель на симптом: если в данных встречаются разные ключи одного симптома, берётся самый частый */
const dataSymKeys=()=>{const cnt={},ord=[];Object.values(S.symptoms).forEach(e=>Object.keys(e.severities||{}).forEach(k=>{if(!(k in cnt))ord.push(k);cnt[k]=(cnt[k]||0)+1}));const best={};ord.forEach(k=>{const c=symCanon(k);if(!(c in best)||cnt[k]>cnt[best[c]])best[c]=k});return ord.filter(k=>best[symCanon(k)]===k)};
function symAll(){const ex=dataSymKeys(),ids=new Set(ex.map(symId).filter(Boolean)),out=[...ex],cust=(S.prefs&&S.prefs.symAdd)||[];
 SYM_ORD.forEach(id=>{if(!ids.has(id)){out.push(id);ids.add(id)}});cust.forEach(l=>{if(!out.includes(l)&&!symId(l))out.push(l)});
 const ord=k=>{const i=SYM_ORD.indexOf(symId(k));return i<0?999:i};return out.sort((a,b)=>ord(a)-ord(b))}
function symVisible(k){const v=((S.prefs&&S.prefs.symVis)||{})[k];if(typeof v==='boolean')return v;return BASE8.includes(symId(k))||dataSymKeys().includes(k)||((S.prefs&&S.prefs.symAdd)||[]).includes(k)}
const symKeys=old=>symAll().filter(k=>symVisible(k)||(old&&sevKeyIn(old,k)!=null));
const EFFS=['better','same','worse'];
function symChips(e){if(!e)return'';if(e.none)return`<span class="chip c0">${t('sym.noneChip')}</span>`;const ch=Object.entries(e.severities||{}).map(([k,v])=>{const l=sevLvl(v);if(sevIsUnk(v))return`<span class="chip cx">${esc(symL(k))} · ${SEV('u')}</span>`;return l===0?'':`<span class="chip c${l||'x'}">${esc(symL(k))} · ${l?SEV(l):esc(v)}</span>`}).join('');return(ch+(e.otherText?`<span class="chip cx">${esc(e.otherText)}</span>`:''))||`<span class="m">${t('sym.emptyRec')}</span>`}
function symExtra(e,full){if(!e)return'';const ug=Object.entries(e.severities||{}).filter(([k,v])=>symUrg(k)&&(sevLvl(v)??1)>0).map(([k])=>symL(k));const ugH=ug.length?`<div class="er" style="font-size:14px;margin-top:8px">${t('obs.urgDay',{x:esc(ug.join(', '))})}</div>`:'';const d=Object.entries(e.details||{}).filter(([,v])=>v&&typeof v==='object').map(([k,v])=>{const bits=[v.since&&okDate(v.since)?t('det.sinceShort',{d:dmn(v.since)}):'',v.dur?t('det.durShort')+' '+esc(v.dur):'',v.desc?esc(v.desc):'',v.action?t('det.didShort')+' '+esc(v.action):'',v.product?t('det.prodShort')+' '+esc(v.product):'',EFFS.includes(v.effect)?t('eff.'+v.effect):'',full&&v.comment?esc(v.comment):''].filter(Boolean);return bits.length?`<div class="m" style="margin-top:6px"><span class="t2">${esc(symL(k))}:</span> ${bits.join(' · ')}</div>`:''}).join('');return ugH+d+(e.note?`<div class="t2" style="margin-top:8px;font-size:15px">«${esc(e.note)}»</div>`:'')}
