function wDelta(L,days){if(L.length<2)return null;const last=L[L.length-1],d=new Date(last.date+'T12:00:00');d.setDate(d.getDate()-days);const lim=dstr(d),base=[...L].reverse().find(w=>w.date<=lim);return base?{v:last.kg-base.kg,from:base}:null}
function wChart(L){const W0=340,H=170,pl=34,pr=10,pt=12,pb=26,xs=L.map(w=>new Date(w.date+'T'+(w.time||'12:00')).getTime()),ys=L.map(w=>wv(w.kg));let x0=Math.min(...xs),x1=Math.max(...xs);if(x1===x0)x1=x0+864e5;let y0=Math.min(...ys),y1=Math.max(...ys);const pd=Math.max(.5,(y1-y0)*.15);y0-=pd;y1+=pd;
 const X=v=>pl+(v-x0)/(x1-x0)*(W0-pl-pr),Y=v=>pt+(y1-v)/(y1-y0)*(H-pt-pb),pts=L.map((w,i)=>[X(xs[i]),Y(wv(w.kg))]);
 return`<svg viewBox="0 0 ${W0} ${H}" width="100%" role="img" aria-label="${t('w.chart')}"><line x1="${pl}" y1="${Y(y1-pd)}" x2="${W0-pr}" y2="${Y(y1-pd)}" stroke="#2a2b37" stroke-dasharray="3 4"/><line x1="${pl}" y1="${Y(y0+pd)}" x2="${W0-pr}" y2="${Y(y0+pd)}" stroke="#2a2b37" stroke-dasharray="3 4"/>
 <text x="${pl-6}" y="${Y(y1-pd)+4}" fill="#9d9baa" font-size="11" text-anchor="end">${fnum(y1-pd,1)}</text><text x="${pl-6}" y="${Y(y0+pd)+4}" fill="#9d9baa" font-size="11" text-anchor="end">${fnum(y0+pd,1)}</text>
 <polyline points="${pts.map(q=>q.join(',')).join(' ')}" fill="none" stroke="#ef9cc4" stroke-width="2.2" stroke-linejoin="round" stroke-linecap="round"/>${pts.map(q=>`<circle cx="${q[0]}" cy="${q[1]}" r="3.6" fill="#fac6df"/>`).join('')}
 <text x="${pl}" y="${H-6}" fill="#9d9baa" font-size="11">${esc(dmn(L[0].date))}</text><text x="${W0-pr}" y="${H-6}" fill="#9d9baa" font-size="11" text-anchor="end">${esc(dmn(L[L.length-1].date))}</text></svg>`}
