async function saveSym(){const k=UI.sym.k,old=S.symptoms[k],enc=sevEnc(),os=(old&&old.severities)||{},sev={};
 const AL=UI.sym.al||{},alv=new Set(Object.values(AL));
 for(const[x,v]of Object.entries(os))if(!(x in UI.sym.v)&&!alv.has(x))sev[x]=v;
 for(const[x,l]of Object.entries(UI.sym.v)){const a=AL[x];
  if(a){if(!UI.sym.t[x]){sev[a]=os[a];continue}sev[x]=l===-2?SEV_UNK:sevVal(l>0?l:0,enc);continue} /* изменённый синоним переносится на общий ключ; прежняя запись уходит в историю исправлений */
  if(!UI.sym.t[x]&&x in os){sev[x]=os[x];continue}if(l===-2){sev[x]=SEV_UNK;continue}if(l>0)sev[x]=sevVal(l,enc);else if(x in os)sev[x]=sevVal(0,enc)}
 const ot=$('#yO').value,none=!Object.values(sev).some(v=>(sevLvl(v)??1)>0||sevIsUnk(v))&&!ot.trim();
 const n={...(old||{}),date:k,none,severities:sev,otherText:ot,note:$('#yN').value},det={...((old&&old.details)||{})};
 document.querySelectorAll('.sdet').forEach(b=>{const fs=b.querySelectorAll('[data-dk]');if(!fs.length)return;const x=fs[0].dataset.dk,o={};fs.forEach(i=>{const v=i.value.trim();if(v)o[i.dataset.f]=v});if(Object.keys(o).length)det[x]=o;else delete det[x]});
 for(const[x,a]of Object.entries(AL)){if(!UI.sym.t[x]){if(det[x]){det[a]=det[x];delete det[x]}}else delete det[a]}
 if(Object.keys(det).length)n.details=det;else delete n.details;if(!old&&Object.values(S.symptoms).some(e=>'flags' in e))n.flags={};
 if(old&&eq(old,n)){closeSheet();toast(t('toast.noChange'));return}
 n.updatedAt=new Date().toISOString();await save(async()=>{if(old)await addHist(k,'symptoms',old,n.updatedAt);await putE('symptoms',k,n);S.symptoms[k]=n;closeSheet();render();toast(old&&!mem?t('toast.savedHist'):okMsg())})}
