const STC=[['purple','#8744A8'],['pink','#D988B5'],['grey','#85838D'],['blue','#8DBFDE'],['choc','#795548'],['milk','#E9DCCE'],['lime','#B5D989'],['peach','#F3C77D'],['blood','#8E2335']];
