 ent.forEach(([k,e])=>{if(isTaken(e.status)){tk++;sum+=+e.doseMg||0}else if(isBad(e.status))ms++;if(okTs(e.updatedAt)&&e.updatedAt>upd)upd=e.updatedAt});
 Object.values(S.symptoms).forEach(e=>{if(okTs(e.updatedAt)&&e.updatedAt>upd)upd=e.updatedAt});
 const rc=has?ent.filter(([k])=>k>=st.startDate&&k<=T).length:0,un=has&&dnT>0?Math.max(0,dnT-rc):null,td=S.intake[D0],p=planFor(T),tg=+st.targetCumulativeMg||0;
 let sk=0;{const d=new Date(T+'T12:00:00');if(!(S.intake[T]&&isTaken(S.intake[T].status)))d.setDate(d.getDate()-1);while(S.intake[dstr(d)]&&isTaken(S.intake[dstr(d)].status)){sk++;d.setDate(d.getDate()-1)}}
