 const times=[...new Set(pairs.map(p=>p[0]))];if(times.length!==pairs.length){alert(t('sl3.tdDup'));return null}
 const anyTD=pairs.some(p=>p[1]!=='');let timeDoses=null;if(anyTD){timeDoses=pairs.map(p=>p[1]===''?NaN:Number(p[1]));if(times.length<2||timeDoses.some(x=>!(x>0))){alert(t('sl3.tdBad'));return null}if(d!=null&&Math.abs(timeDoses.reduce((a,x)=>a+x,0)-d)>1e-9){alert(t('sl3.tdSum',{s:fnum(timeDoses.reduce((a,x)=>a+x,0)),d:fnum(d)}));return null}}
 if(!DATE.test(from)){alert(t('drug.needFrom'));return null}if((d!=null&&!(d>0))||(k!=null&&!(k>0))||caps.some(c=>!(c>0))){alert(t('drug.bad'));return null}
