/* ---------- распознавание анализов по фото (claude sample, только с подтверждением) ---------- */
let SMP=null;
async function ocrInit(){try{if(!window.claude||!claude.use)return;SMP=await claude.use('sample');if(!SMP)return;const L=await SMP.limits().catch(()=>null);UI.ocrTypes=L&&L.images?L.images.mediaTypes:null;if(UI.ocrTypes&&$('#lbItems')&&!$('#ocrIn'))ocrSlot()}catch(e){SMP=null}}
const ocrBtn=()=>UI.ocrTypes?`<label class="btn sec2" style="margin-top:8px">📷 ${t('ocr.btn')}<input type="file" id="ocrIn" accept="${esc(UI.ocrTypes.join(','))}" hidden></label><div class="hint">${t('ocr.hint')}</div>`:'';
function ocrSlot(){const w=$('#ocrW');if(w)w.innerHTML=ocrBtn()}
const OCR_PROMPT=()=>`This is a photo of a medical laboratory test report. Extract ONLY what is clearly printed. Do not guess, correct, convert units or recalculate anything. Keep indicator names and values exactly in the document's language and notation (decimal comma or point, signs like < or >).
Reply with only JSON of this shape:
{"date":"YYYY-MM-DD or null (the sample collection date if printed)","lab":"laboratory name or null","items":[{"name":"indicator name","value":"value as printed","unit":"unit as printed or empty","lo":"lower reference bound or empty","hi":"upper reference bound or empty"}]}
If a reference range is one-sided (e.g. "< 5"), put the bound in the matching field and leave the other empty. Skip any row you cannot read with confidence. If the image is not a lab report, return {"date":null,"lab":null,"items":[]}.`;
async function ocrRun(f){const out=$('#ocrOut');if(!out||!SMP)return;
 if(!(UI.ocrTypes||[]).includes(f.type)){out.innerHTML=`<div class="er">${t('ocr.type')}</div>`;return}
 if(f.size>12e6){alert(t('lab.tooBig',{n:esc(f.name)}));return}
 const ctl=new AbortController();UI.ocrCtl=ctl;out.innerHTML=`<div class="wn">${t('ocr.wait')} <span class="pk" data-act="ocrStop">${t('ocr.stop')}</span></div>`;
 let fileRec=null;try{await save(async()=>{fileRec=await addFile(f);UI.pf.push(fileRec);const b=$('#pfBox');if(b)b.innerHTML=fileChips(UI.pf)})}catch(e){}
 let r;try{r=await SMP.json(OCR_PROMPT(),{images:[f],signal:ctl.signal})}catch(e){UI.ocrCtl=null;if(!$('#ocrOut'))return;
  const c=e&&e.code,m={cancelled:'',not_granted:'ocr.eGrant',sampling_disabled:'ocr.eGrant',images_unavailable:'ocr.eGrant',rate_limited:'ocr.eRate',image_rejected:'ocr.eImg',refused:'ocr.eRead',empty_completion:'ocr.eRead',invalid_json:'ocr.eRead'}[c];
  if(c==='not_granted'||c==='sampling_disabled'||c==='images_unavailable'){UI.ocrTypes=null;ocrSlot()}
  $('#ocrOut').innerHTML=m===''?'':`<div class="er">${t(m||'ocr.eOther')}</div>${fileRec?`<div class="hint">${t('ocr.kept')}</div>`:''}`;return}
 UI.ocrCtl=null;if(!$('#ocrOut'))return;
 const S_=v=>v==null?'':String(v).trim().slice(0,80);const items=(r&&Array.isArray(r.items)?r.items:[]).map(x=>({name:S_(x&&x.name),value:S_(x&&x.value),unit:S_(x&&x.unit),lo:S_(x&&x.lo),hi:S_(x&&x.hi)})).filter(x=>x.name&&x.value).slice(0,80);
 if(!items.length){$('#ocrOut').innerHTML=`<div class="er">${t('ocr.none')}</div>${fileRec?`<div class="hint">${t('ocr.kept')}</div>`:''}`;return}
 document.querySelectorAll('.lrow').forEach(row=>{if(![...row.querySelectorAll('input')].some(i=>i.value.trim()))row.remove()});
 $('#lbItems').insertAdjacentHTML('beforeend',items.map(it=>labRow(it).replace('class="lrow card" style="','class="lrow card ocr" style="box-shadow:inset 0 0 0 1.5px var(--wr);')).join(''));
 const dd=r&&typeof r.date==='string'&&okDate(r.date)&&r.date<=today()?r.date:'';const lab=r&&typeof r.lab==='string'?S_(r.lab):'';
 $('#ocrOut').innerHTML=`<div class="wn">${tn('ocr.found',items.length)}</div>${dd&&dd!==$('#lbD').value?`<div class="hint">${t('ocr.date',{d:esc(fdate(dd))})} <span class="pk" data-act="ocrDate" data-d="${dd}">${t('end.useLast')}</span></div>`:''}${lab&&!$('#lbL').value.trim()?`<div class="hint">${t('ocr.lab',{x:esc(lab)})} <span class="pk" data-act="ocrLab" data-x="${esc(lab)}">${t('end.useLast')}</span></div>`:''}
 <label class="ck" style="margin-top:12px;align-items:flex-start"><input type="checkbox" id="ocrOk"><span>${t('ocr.confirm')}</span></label>`}

