/* ---------- статистика курса и отчёт для врача ---------- */
const ST_CH=['daily','cum','sym','diary','weight'],stChOn=c=>((S.prefs&&S.prefs.stCh)||{})[c]!==false;
const addDay=(k,n)=>{const d=new Date(k+'T12:00:00');d.setDate(d.getDate()+n);return dstr(d)};
const dayList=(a,b)=>{const o=[];for(let k=a;k<=b&&o.length<4000;k=addDay(k,1))o.push(k);return o};
function firstRecDay(){const ks=[...Object.keys(S.intake),...Object.keys(S.symptoms),...wList().map(w=>w.date)].filter(okDate).sort();return ks[0]||today()}
function stRange(){const T=today(),p=UI.stP||'30',sc_=courseList().length?S.courses[statCourse()]:null,st=sc_&&sc_.start?sc_.start:(S.settings.startDate&&okDate(S.settings.startDate)?S.settings.startDate:firstRecDay());
 if(sc_&&sc_.end&&sc_.id!==(curCourse()||{}).id&&p!=='custom')return[sc_.start,sc_.end<T?sc_.end:T];
 if(p==='custom'){let a=okDate(UI.stF||'')?UI.stF:addDay(T,-29),b=okDate(UI.stT||'')?UI.stT:T;if(b>T)b=T;if(a>b)[a,b]=[b,a];return[a,b]}
 if(p==='all'){const a=st<T?st:firstRecDay();return[a>T?T:a,T]}const n=+p;return[addDay(T,-(n-1)),T]}
function stData(a,b){const ks=dayList(a,b),cid=courseList().length?statCourse():null,sc=cid?S.courses[cid]:null,st0=sc&&sc.start?sc.start:(S.settings.startDate&&okDate(S.settings.startDate)?S.settings.startDate:''),IN=k=>{const e=S.intake[k];return e&&inCourse(e,cid)?e:null};let cumBefore=0;
 for(const[k,e]of Object.entries(S.intake))if(k<a&&inCourse(e,cid)&&isTaken(e.status))cumBefore+=+e.doseMg||0;
 let cum=cumBefore;const days=ks.map(k=>{const e=IN(k),tk=!!(e&&isTaken(e.status)),ms=!!(e&&!tk&&e.status),dose=tk?(+e.doseMg||0):0,plan=planFor(k);cum+=dose;
  const se=S.symptoms[k],sv=se&&se.severities?Object.entries(se.severities).map(([s,v])=>[s,sevLvl(v)??1]).filter(([,l])=>l>0):[];
  return{k,tk,ms,un:!e&&(!st0||k>=st0)&&k<today(),dose,plan,cum,odd:tk&&plan!=null&&+e.doseMg!==+plan,symRec:!!se,sv,smax:sv.reduce((m,[,l])=>Math.max(m,l),0)}});
 return{a,b,ks,days,cumBefore,cum}}
/* единственный расчёт аналитики симптомов: им пользуются и вкладка «побочки», и статистика, и отчёт */
function symFreq(D){const rec=D.days.filter(d=>d.symRec),cs=[...new Set(D.days.flatMap(d=>d.sv.map(([x])=>symCanon(x))))],all=Object.keys(S.symptoms).sort();
 return cs.map(c=>{const lv=d=>d.symRec?(sevOf(S.symptoms[d.k],c)||0):null,ls=rec.map(lv),on=ls.filter(l=>l>0);if(!on.length)return null;
  let run=0,best=0;const runs=[];D.days.forEach(d=>{const l=lv(d);if(l>0){run++;best=Math.max(best,run)}else{if(run)runs.push(run);run=0}});if(run)runs.push(run);
  let cur=0;for(let i=D.days.length-1;i>=0;i--){const l=lv(D.days[i]);if(l===null){if(i===D.days.length-1)continue;break}if(l>0)cur++;else break}
  let trend='';if(ls.length>=4){const h=Math.floor(ls.length/2),av=a=>a.reduce((p,v)=>p+v,0)/a.length,dl=av(ls.slice(ls.length-h))-av(ls.slice(0,h));trend=dl>.34?'up':dl<-.34?'down':'same'}
  const fst=all.find(k=>(sevOf(S.symptoms[k],c)||0)>0);
  return{s:c,days:on.length,of:rec.length,max:Math.max(...on),eps:runs.length,avgLen:runs.length?runs.reduce((p,v)=>p+v,0)/runs.length:0,best,cur,trend,cd:fst?courseDay(fst):0}}).filter(Boolean).sort((p,q)=>q.days-p.days||q.max-p.max)}
function careFreq(a,b){const m={};for(const[k,c]of Object.entries(S.care)){if(k<a||k>b||!c)continue;for(const id of new Set([...(c.am||[]),...(c.pm||[])]))m[id]=(m[id]||0)+1}return Object.entries(m).map(([id,n])=>({name:(S.products[id]||{}).name||id,n})).sort((p,q)=>q.n-p.n)}
function labsIn(a,b){return labList().filter(l=>l.date>=a&&l.date<=b).sort((p,q)=>p.date.localeCompare(q.date))}
const labFlag=it=>{const v=parseFloat(String(it.value).replace(',','.').replace(/[<>≤≥\s]/g,'')),lo=parseFloat(String(it.lo||'').replace(',','.')),hi=parseFloat(String(it.hi||'').replace(',','.'));if(!isFinite(v))return'';if(isFinite(hi)&&v>hi)return'↑';if(isFinite(lo)&&v<lo)return'↓';return''};
/* svg: цвета передаются явно, чтобы тот же график работал и в приложении, и в печатном отчёте */
function svgLine(pts,o={}){const W=340,H=o.h||150,pl=40,pr=10,pt=12,pb=22;if(!pts.length)return'';const ys=pts.map(p=>p.y).concat(o.ref!=null?[o.ref]:[]);let y0=o.y0??Math.min(...ys),y1=o.y1??Math.max(...ys);if(y1===y0)y1=y0+1;
 const X=i=>pl+(pts.length<2?(W-pl-pr)/2:i*(W-pl-pr)/(pts.length-1)),Y=v=>pt+(H-pt-pb)*(1-(v-y0)/(y1-y0)),c=o.c||'#ef9cc4',g=o.g||'#30313f',tx=o.tx||'#9d9baa';
 const d=pts.map((p,i)=>`${i?'L':'M'}${X(i).toFixed(1)},${Y(p.y).toFixed(1)}`).join(''),lab=[0,Math.floor((pts.length-1)/2),pts.length-1].filter((v,i,a)=>a.indexOf(v)===i);
 return`<svg viewBox="0 0 ${W} ${H}" width="100%" role="img" aria-label="${esc(o.al||'')}" style="display:block">${[y0,(y0+y1)/2,y1].map(v=>`<line x1="${pl}" x2="${W-pr}" y1="${Y(v)}" y2="${Y(v)}" stroke="${g}" stroke-width="1"/><text x="${pl-6}" y="${Y(v)+4}" text-anchor="end" font-size="10" fill="${tx}">${fnum(v,o.dp??0)}</text>`).join('')}
 ${o.ref!=null?`<line x1="${pl}" x2="${W-pr}" y1="${Y(o.ref)}" y2="${Y(o.ref)}" stroke="${o.rc||'#90ddc1'}" stroke-dasharray="4 4"/>`:''}<path d="${d}" fill="none" stroke="${c}" stroke-width="2.2" stroke-linejoin="round"/>${pts.length<40?pts.map((p,i)=>`<circle cx="${X(i)}" cy="${Y(p.y)}" r="2.4" fill="${c}"/>`).join(''):''}
 ${lab.map(i=>`<text x="${X(i)}" y="${H-6}" text-anchor="${i===0?'start':i===pts.length-1?'end':'middle'}" font-size="10" fill="${tx}">${esc(dmn(pts[i].x))}</text>`).join('')}</svg>`}
function svgBars(D,o={}){const W=340,H=o.h||140,pl=40,pr=10,pt=12,pb=22,n=D.days.length,mx=Math.max(1,...D.days.map(d=>Math.max(d.dose,d.plan||0))),bw=(W-pl-pr)/n,Y=v=>pt+(H-pt-pb)*(1-v/mx),c=o.c||'#ef9cc4',g=o.g||'#30313f',tx=o.tx||'#9d9baa',ms=o.ms||'#b9a3e6';
 const plan=D.days.map((d,i)=>d.plan!=null?`${i&&D.days[i-1].plan!=null?'L':'M'}${(pl+i*bw).toFixed(1)},${Y(d.plan).toFixed(1)}H${(pl+(i+1)*bw).toFixed(1)}`:'').join('');
 return`<svg viewBox="0 0 ${W} ${H}" width="100%" role="img" aria-label="${esc(o.al||'')}" style="display:block">${[0,mx/2,mx].map(v=>`<line x1="${pl}" x2="${W-pr}" y1="${Y(v)}" y2="${Y(v)}" stroke="${g}"/><text x="${pl-6}" y="${Y(v)+4}" text-anchor="end" font-size="10" fill="${tx}">${fnum(v,0)}</text>`).join('')}
 ${D.days.map((d,i)=>d.tk?`<rect x="${pl+i*bw+bw*.15}" y="${Y(d.dose)}" width="${Math.max(1,bw*.7)}" height="${Math.max(0,Y(0)-Y(d.dose))}" rx="${Math.min(3,bw*.3)}" fill="${c}"/>`:d.ms?`<rect x="${pl+i*bw+bw*.15}" y="${Y(0)-3}" width="${Math.max(1,bw*.7)}" height="3" fill="${ms}"/>`:'').join('')}
 <path d="${plan}" fill="none" stroke="${o.pc||'#90ddc1'}" stroke-width="1.5" stroke-dasharray="3 3"/>
 <text x="${pl}" y="${H-6}" font-size="10" fill="${tx}">${esc(dmn(D.a))}</text><text x="${W-pr}" y="${H-6}" text-anchor="end" font-size="10" fill="${tx}">${esc(dmn(D.b))}</text></svg>`}
function svgSym(D,o={}){const W=340,H=o.h||70,pl=40,pr=10,n=D.days.length,bw=(W-pl-pr)/n,cs=o.cs||['#2a2a33','#5e4658','#b07d98','#ef9cc4'],nr=o.nr||'#1b1b23',tx=o.tx||'#9d9baa';
 return`<svg viewBox="0 0 ${W} ${H}" width="100%" role="img" aria-label="${esc(o.al||'')}" style="display:block">${D.days.map((d,i)=>`<rect x="${pl+i*bw+.5}" y="${8+(3-d.smax)*10}" width="${Math.max(1,bw-1)}" height="${d.symRec?Math.max(4,d.smax*10+4):4}" rx="2" fill="${d.symRec?cs[d.smax]:nr}"/>`).join('')}
 <text x="${pl}" y="${H-4}" font-size="10" fill="${tx}">${esc(dmn(D.a))}</text><text x="${W-pr}" y="${H-4}" text-anchor="end" font-size="10" fill="${tx}">${esc(dmn(D.b))}</text></svg>`}
const dyIn=(a,b)=>Object.values(S.diary).filter(d=>d&&d.date>=a&&d.date<=b&&!dyEmpty(d)).sort((p,q)=>p.date.localeCompare(q.date));
const dyChart=(L,f,o={})=>{const P=L.filter(d=>d[f]);return P.length>1?svgLine(P.map(d=>({x:d.date,y:d[f]})),{h:110,y0:1,y1:5,...o}):''};
function stSummary(D){const tk=D.days.filter(d=>d.tk).length,ms=D.days.filter(d=>d.ms).length,un=D.days.filter(d=>d.un).length,odd=D.days.filter(d=>d.odd).length,sum=D.days.reduce((p,d)=>p+d.dose,0),sd=D.days.filter(d=>d.symRec).length,none=D.days.filter(d=>d.symRec&&!d.sv.length).length;return{tk,ms,un,odd,sum,sd,none}}
function vStats(){const[a,b]=stRange(),D=stData(a,b),s=stSummary(D),F=symFreq(D),WL=wValid().filter(w=>w.date>=a&&w.date<=b),LB=labsIn(a,b),CF=careFreq(a,b),tg=+S.settings.targetCumulativeMg||null,p=UI.stP||'30';
 const chg=L=>L.length>1?(L[L.length-1].kg-L[0].kg):null,regs=regList().filter(r=>r.from<=b);
 return`${back(t('nav.ov'))}<div class="eye">${t('app.name')}</div><h1>${t('stx.title')}</h1>${courseChips(statCourse(),'stC')}
 <div class="seg" style="margin:0 0 8px">${['7','14','30','all','custom'].map(v=>`<button class="${p===v?'on':''}" data-act="stP" data-v="${v}">${t('stx.p.'+v)}</button>`).join('')}</div>
 ${p==='custom'?`<div class="row" style="flex-wrap:nowrap;gap:8px"><input type="date" id="stF" value="${esc(a)}" max="${today()}" style="margin:0"><input type="date" id="stT" value="${esc(b)}" max="${today()}" style="margin:0"></div>`:''}
 <div class="m" style="margin:6px 2px 0">${esc(fdate(a))} — ${esc(fdate(b))} · ${tn('u.days',D.ks.length)}</div>
 <button class="btn pri blk" style="margin-top:14px" data-act="repSheet">📄 ${t('rep.open')}</button>
 <div class="sec">${t('stx.intake')}</div><div class="g2">${stc(t('ov.daysTaken'),s.tk)}${stc(t('ov.missed'),s.ms)}${stc(t('ov.unmarked'),s.un)}${stc(t('stx.odd'),s.odd,t('stx.oddHint'))}</div>
 <div class="card"><div class="t2" style="margin-bottom:6px">${t('stx.daily')}</div>${stChOn('daily')?svgBars(D,{al:t('stx.daily')})+`<div class="m" style="font-size:13px;margin-top:6px">${t('stx.dailyLg')}</div>`:`<div class="m">${t('stx.hidden')}</div>`}</div>
 <div class="card"><div class="row sp"><span class="t2">${t('stx.cum')}</span><span class="ser" style="font-size:28px">${fnum(D.cum)} <span class="u">${t('u.mg')}</span></span></div><div class="m" style="font-size:13px">${t('stx.inPeriod',{n:fnum(s.sum)})}${tg?' · '+t('ov.goalOf',{a:fnum(D.cum),b:fnum(tg)}):''}</div>${stChOn('cum')?svgLine(D.days.map(d=>({x:d.k,y:d.cum})),{y0:0,ref:tg&&tg<=D.cum*1.6?tg:null,al:t('stx.cum')}):''}${tg&&tg<=D.cum*1.6?`<div class="m" style="font-size:13px;margin-top:4px">${t('stx.goalLine')}</div>`:''}</div>
 ${regs.length?`<div class="card"><div class="t2" style="margin-bottom:6px">${t('stx.regs')}</div>${regs.map(r=>`<div class="m" style="padding:3px 0">${esc(fdate(r.from))} · ${esc(regLine(r))}</div>`).join('')}</div>`:''}
 <div class="sec">${t('stx.sym')}</div><div class="card"><div class="m" style="font-size:13px;margin-bottom:6px">${t('stx.symRec',{a:s.sd,b:D.ks.length,c:s.none})}</div>${stChOn('sym')?svgSym(D,{al:t('stx.sym')})+`<div class="m" style="font-size:13px;margin-top:4px">${t('stx.symLg')}</div>`:''}
 ${F.length?`<table style="margin-top:10px"><tr><td class="m">${t('stx.symCol')}</td><td class="m" style="text-align:right">${t('stx.daysCol')} · ${t('ss.max')} · ${t('stx.epCol')}</td></tr>${F.slice(0,12).map(f=>`<tr><td>${esc(symL(f.s))}${f.trend?` <span class="m">${t('stx.tr.'+f.trend)}</span>`:''}</td><td>${f.days} · ${esc(SEV(f.max))} · ${f.eps}${f.eps?` <span class="m">(${t('stx.avgLen',{n:fnum(f.avgLen,1)})})</span>`:''}</td></tr>`).join('')}</table>`:`<div class="m">${t('ss.none')}</div>`}<div class="hint">${t('ss.foot')}</div></div>
 <div class="sec">${t('dy.statsH')}</div><div class="card">${(()=>{const L=dyIn(a,b);if(!L.length)return`<span class="m">${t('stx.noData')}</span>`;const av=f=>{const v=L.filter(d=>d[f]).map(d=>d[f]);return v.length?fnum(v.reduce((p,c)=>p+c,0)/v.length,1):'—'};return`<div class="m" style="font-size:13px">${t('dy.statsInfo',{n:L.length,w:av('well'),s:av('skin')})}</div>${stChOn('diary')&&dyChart(L,'well',{al:t('dy.well')})?`<div class="t2" style="margin-top:8px">${t('dy.well')}</div>`+dyChart(L,'well',{al:t('dy.well')}):''}${stChOn('diary')&&dyChart(L,'skin',{c:'#b9a3e6',al:t('dy.skin')})?`<div class="t2" style="margin-top:8px">${t('dy.skin')}</div>`+dyChart(L,'skin',{c:'#b9a3e6',al:t('dy.skin')}):''}<div class="hint">${t('dy.scaleHint')}</div>`})()}</div>
 <div class="sec">${t('w.title')}</div><div class="card">${WL.length?`<div class="m" style="font-size:13px">${t('stx.wInfo',{n:WL.length})}${chg(WL)!=null?' · '+t('stx.wChg',{v:sgn(chg(WL)),u:wUL()}):''}</div>${WL.length>1&&stChOn('weight')?svgLine(WL.map(w=>({x:w.date,y:wv(w.kg)})),{dp:1,al:t('w.chart')}):''}`:`<span class="m">${t('stx.noData')}</span>`}</div>
 <div class="sec">${t('lab.title')}</div><div class="card">${LB.length?LB.map(l=>`<div style="padding:6px 0;border-bottom:1px solid #22232d"><div class="t2">${esc(fdate(l.date))}${l.title?' · '+esc(l.title):''}</div><div class="m" style="font-size:13px">${(l.items||[]).map(it=>`${esc(it.name)}: ${esc(it.value)}${it.unit?' '+esc(it.unit):''}${labFlag(it)?` <b style="color:var(--wr)">${labFlag(it)}</b>`:''}`).join(' · ')}</div></div>`).join('')+`<div class="hint">${t('stx.labHint')}</div>`:`<span class="m">${t('stx.noData')}</span>`}</div>
 <div class="sec">${t('stx.care')}</div><div class="card">${CF.length?CF.slice(0,10).map(c=>`<div class="row sp" style="flex-wrap:nowrap;padding:4px 0"><span>${esc(c.name)}</span><span class="m">${tn('stx.uses',c.n)}</span></div>`).join(''):`<span class="m">${t('stx.noCare')}</span>`}</div>
 <div class="m" style="margin:16px 4px 0;font-size:13px">${t('ov.disclaimer')}</div>`}
