/* ================= модель данных ТЗ № 3, этап 1 =================
   курс — отдельная сущность (коллекция courses). активный курс отражается в S.settings
   (startDate, endPlanned, endActual, targetCumulativeMg, drugName, plannedDoseMg) — это рабочая проекция,
   которую читает остальной код; источник истины для истории курсов — документы courses.
   записи дневника (intake, symptoms, diary, photos, regimens) получают course_id при записи;
   запись без course_id принадлежит курсу LEGACY_COURSE (так старые данные не переписываются).
   вес, анализы, консультации, вопросы, средства, уход, шаги — данные профиля, без курса.
   день записи — ключ YYYY-MM-DD (local_date): он никогда не пересчитывается при смене часового пояса;
   часовой пояс момента записи хранится в поле tz. */
const SCHEMA=3,LEGACY_COURSE='course-1';
const COURSE_BOUND=['intake','symptoms','diary','regimens'];
const COURSE_ST=['active','paused','completed','archived'];
const devTZ=()=>{try{return Intl.DateTimeFormat().resolvedOptions().timeZone||''}catch(e){return''}};
const courseList=()=>Object.values(S.courses||{}).filter(c=>c&&c.id).sort((a,b)=>String(a.start||'').localeCompare(String(b.start||''))||String(a.createdAt).localeCompare(String(b.createdAt)));
const curCourse=()=>(S.settings&&S.courses[S.settings.course_id])||activeCourse();
const activeCourse=()=>{const L=courseList();return L.find(c=>c.status==='active')||L.find(c=>c.status==='paused')||null};
const courseOf=rec=>rec&&rec.course_id||LEGACY_COURSE;
/* курс для новой записи: тот, в чей период попадает дата, иначе активный; присваивается один раз и дальше хранится явно */
function courseForDate(k){const L=courseList();for(const c of L)if(c.start&&c.start<=k&&(!c.end||k<=c.end))return c.id;const a=activeCourse();return a?a.id:(L.length?L[L.length-1].id:null)}
/* вызывается из stSet: только НОВАЯ запись получает курс и часовой пояс устройства; старые записи и импорт не трогаются */
function stamp(path,obj){if(UI.noStamp||!obj||typeof obj!=='object'||!BASE||!path.startsWith(BASE+'/root/'))return;const rest=path.slice(BASE.length+6).split('/');if(rest.length!==2)return;const[c,k]=rest;
 if(!COURSE_BOUND.includes(c)||(S[c]&&S[c][k]))return;
 if(!obj.course_id){const d=c==='regimens'?obj.from:k;const cid=DATE.test(d||'')?courseForDate(d):null;if(cid)obj.course_id=cid}
 if((c==='intake'||c==='symptoms')&&!obj.tz){const z=devTZ();if(z)obj.tz=z}}
/* ---------- миграция до схемы 3: только добавление, существующие записи не изменяются ---------- */
async function migrate(){if(mem)return{skipped:'mem'};const before=S.meta.schema||1;let created=null;
 if(!courseList().length){const st=S.settings||{},dates=[...Object.keys(S.intake),...Object.keys(S.symptoms)].filter(k=>DATE.test(k)).sort();
  const has=!!(st.startDate||dates.length||Object.keys(S.regimens||{}).length);
  if(has){const now=new Date().toISOString(),start=DATE.test(st.startDate||'')?st.startDate:(dates[0]||today());
   const c={id:LEGACY_COURSE,start,status:st.endActual&&DATE.test(st.endActual)?'completed':'active',unit:'mg',createdAt:now,updatedAt:now,migratedFrom:'settings',
    ...(st.endActual?{end:st.endActual}:{}),...(st.endPlanned?{endPlanned:st.endPlanned}:{}),...(st.targetCumulativeMg!=null?{targetCumulativeMg:st.targetCumulativeMg}:{}),...(st.drugName?{drug:st.drugName}:{})};
   await W(()=>stSet(BASE+'/root/courses/'+c.id,c));S.courses[c.id]=c;created=c.id}}
 if(S.settings&&!S.settings.course_id&&courseList().length){const c=activeCourse()||courseList().at(-1),ns={...S.settings,course_id:c.id};await W(()=>stSet(BASE+'/settings',ns));S.settings=ns}
 if(before<SCHEMA){const nm={...S.meta,schema:SCHEMA,migratedAt:S.meta.migratedAt||new Date().toISOString()};await W(()=>stSet(BASE+'/meta',nm));S.meta=nm}
 return{before,after:S.meta.schema,created}}
/* курс, который сейчас показан в настройках, повторяет их поля; вызывается после каждого сохранения настроек */
async function syncCourse(){const a=curCourse();if(!a){if(!courseList().length)await migrate();return}const st=S.settings,n={...a};
 const put=(f,v)=>{if(v==null||v===''){delete n[f]}else n[f]=v};
 if(DATE.test(st.startDate||''))n.start=st.startDate;put('end',st.endActual);put('endPlanned',st.endPlanned);put('targetCumulativeMg',st.targetCumulativeMg);put('drug',st.drugName);put('plannedDoseMg',st.plannedDoseMg);
 if(n.end&&n.status==='active')n.status='completed';if(!n.end&&n.status==='completed')n.status='active';
 if(eq(n,a))return;n.updatedAt=new Date().toISOString();await W(()=>stSet(BASE+'/root/courses/'+a.id,n));S.courses[a.id]=n}
/* накопленная доза: сумма только отмеченных принятых доз; плановые дозы и неотмеченные дни не учитываются */
function cumInfo(cid){let sum=0,taken=0,missed=0,noDose=0;for(const[k,e]of Object.entries(S.intake)){if(cid&&courseOf(e)!==cid)continue;if(isTaken(e.status)){taken++;const d=+e.doseMg;if(d>0)sum+=d;else noDose++}else if(isBad(e.status))missed++}
 return{sum,taken,missed,noDose}}

/* ================= ТЗ № 3, этап 3: пять разделов, главная, чек-ин, приёмы по времени, первый запуск =================
   разделы: главная (ov) · дневник (diary: календарь, побочки, фото) · здоровье (health) · уход (care) · профиль (data).
   существующие экраны не переписываются: дневник и здоровье собирают их, старые адреса вкладок перенаправляются. */
const DV=['cal','sym','photo'];
const P3_ICONS={diary:'cal',health:'heart'};
/* дневник: те же экраны календаря, побочек и фото, переключатель под заголовком */
function vDiary(){const v=DV.includes(UI.dv)?UI.dv:'cal',html=({cal:vCal,sym:vSym,photo:vPhoto}[v])();
 const seg=`<div style="display:grid;grid-template-columns:repeat(3,1fr);gap:6px;margin:0 0 16px">${DV.map(x=>`<button class="chip ${v===x?'c3':'cx'}" style="border:0;font:inherit;font-size:14px;cursor:pointer;margin:0;padding:11px 4px;text-align:center;min-width:0" data-act="dvTab" data-v="${x}" aria-pressed="${v===x}">${t('nav.'+x)}</button>`).join('')}</div>`;
 const more=`<div class="row" style="gap:8px;margin:18px 0 0"><button class="chip cx" style="border:0;font:inherit;font-size:14px;cursor:pointer" data-act="sub" data-s="weight">${t('w.title')} ›</button><button class="chip cx" style="border:0;font:inherit;font-size:14px;cursor:pointer" data-act="sub" data-s="activity">${t('act.steps')} ›</button><button class="chip cx" style="border:0;font:inherit;font-size:14px;cursor:pointer" data-act="qaDy" data-d="${today()}">${t('dy.title')} ›</button></div>`;
 const i=html.indexOf('</h1>');return(i<0?seg+html:html.slice(0,i+5)+seg+html.slice(i+5)).replace(/^<div class="eye">[\s\S]*?<\/div>/,`<div class="eye">${t('nav.diary')}</div>`)+more}
/* здоровье: назначения, анализы, консультации, вес, статистика и отчёт */
function vHealth(){const L=wValid(),lw=L[L.length-1],lb=labList()[0],oq=qOpen().length;
 const row=(act,s,title,sub)=>`<button class="card row sp" style="width:100%;font:inherit;color:var(--t);text-align:left;cursor:pointer;flex-wrap:nowrap" data-act="${act}"${s?` data-s="${s}"`:''}><span style="min-width:0"><span style="font-size:17px">${title}</span><br><span class="m">${sub}</span></span><span class="m">›</span></button>`;
 return`<div class="eye">${t('nav.health')}</div><h1>${t('hl.title')}</h1>${medCard()}
 ${drugBtn()}
 ${row('sub','labs',t('lab.title'),lb?t('hl.labLast',{n:labList().length,d:esc(fdate(lb.date))}):t('hl.none'))}
 ${row('sub','consults',t('con.title'),tn('hl.con',conList().length)+(oq?' · '+tn('q.nOpen',oq):''))}
 ${row('sub','weight',t('w.title'),lw?`${wF(lw.kg)} ${wUL()} · ${esc(fdate(lw.date))}`:t('hl.none'))}
 ${row('sub','stats',t('stx.title'),t('rep.open'))}
 <div class="m" style="font-size:13px;margin:12px 4px 0">${t('hl.note')}</div>`}
/* ---------- приёмы по времени (ADR-3) ----------
   работают, только если в схеме для каждого времени явно указана доза на приём (timeDoses).
   запись дня остаётся одна: slots = {s1:{id,status,doseMg,time?,at}}; верхние поля status/doseMg — сумма,
   поэтому календарь, статистика, отчёт и накопленная доза работают без изменений. id приёма = курс:дата:слот. */
function slotsFor(k){const r=regAt(k);if(!r||!Array.isArray(r.times)||r.times.length<2||!Array.isArray(r.timeDoses)||r.timeDoses.length!==r.times.length||!r.timeDoses.every(d=>+d>0))return null;
 return r.times.map((tm,i)=>({sid:'s'+(i+1),time:tm,dose:+r.timeDoses[i]}))}
function slotAgg(k,slots,base){const L=Object.values(slots),tk=L.filter(s=>isTaken(s.status)),ms=L.filter(s=>isBad(s.status)),plan=slotsFor(k),total=plan?plan.length:L.length;
 if(!tk.length&&!ms.length)return null;const n={...(base||{}),slots,status:tk.length?takenSt():missedSt(),doseMg:tk.length?tk.reduce((a,s)=>a+(+s.doseMg||0),0):null};
 if(tk.length&&tk.length<total)n.partial=true;else delete n.partial;return n}
async function markSlot(k,sid,act){const plan=slotsFor(k),sl=plan&&plan.find(x=>x.sid===sid);if(!sl)return;const it=S.intake[k],now=new Date().toISOString(),slots={...((it&&it.slots)||{})};
 if(act==='u')delete slots[sid];else{const prev=slots[sid]||{},cid=(it&&it.course_id)||courseForDate(k)||LEGACY_COURSE;
  slots[sid]={...prev,id:`${cid}:${k}:${sid}`,status:act==='t'?takenSt():missedSt(),doseMg:act==='t'?(prev.doseMg!=null&&isTaken(prev.status)?prev.doseMg:sl.dose):null,at:prev.status===(act==='t'?takenSt():missedSt())?prev.at:now}}
 const n=slotAgg(k,slots,it);if(it&&n&&eq(it,{...n,updatedAt:it.updatedAt}))return;
 await save(async()=>{if(it)await addHist(k,'intake',it,now,!n);if(!n){await W(()=>DB.doc(BASE+'/root/intake/'+k).delete());delete S.intake[k]}else{n.updatedAt=now;await putE('intake',k,n);S.intake[k]=n}render();toast(okMsg())})}
/* карточка сегодняшнего приёма для схемы с несколькими приёмами: отдельная строка и отдельные кнопки на каждый */
