function slotsFromForm(k){const plan=slotsFor(k),old=(S.intake[k]||{}).slots||{},out={},now=new Date().toISOString(),cid=((S.intake[k]||{}).course_id)||courseForDate(k)||LEGACY_COURSE;
 for(const p of plan){const v=document.querySelector(`.dSl[data-sid="${p.sid}"]`).value;if(!v)continue;const dv=num(document.querySelector(`.dSlD[data-sid="${p.sid}"]`).value),tm=document.querySelector(`.dSlT[data-sid="${p.sid}"]`).value;
  if(dv!==''&&!(typeof dv==='number'&&dv>0))return{err:true};const st=v==='t'?takenSt():missedSt(),o=old[p.sid]||{};
  out[p.sid]={id:`${cid}:${k}:${p.sid}`,status:st,doseMg:v==='t'?(dv===''?p.dose:dv):null,at:o.status===st?(o.at||now):now,...(tm?{time:tm}:{})}}
 return{slots:out}}
