function ckKeys(){const T=today(),cnt={},vis=symKeys(S.symptoms[T]);for(const[k,e]of Object.entries(S.symptoms)){if(k>T)continue;const age=(Date.parse(T)-Date.parse(k))/864e5;if(age>30)continue;Object.entries(e.severities||{}).forEach(([x,v])=>{const c=symCanon(x);if((sevLvl(v)||0)>0)cnt[c]=(cnt[c]||0)+1})}
 const keys=vis.map(x=>[x,cnt[symCanon(x)]||0]);keys.sort((a,b)=>b[1]-a[1]);return keys.slice(0,10).map(x=>x[0])}
