/* ================= хранилище PWA: IndexedDB =================
   тот же интерфейс, что у хранилища артефакта: DB.doc(path).get/set/delete, DB.collection(path).get/doc.
   один object store «docs», ключ — путь документа. запись считается выполненной только после
   завершения транзакции (oncomplete), поэтому статус «сохранено» не показывается раньше времени. */
const IDB_NAME='kurs',IDB_STORE='docs';
function idbOpen(){return new Promise((res,rej)=>{let r;try{r=indexedDB.open(IDB_NAME,1)}catch(e){rej(e);return}
 r.onupgradeneeded=()=>{const d=r.result;if(!d.objectStoreNames.contains(IDB_STORE))d.createObjectStore(IDB_STORE)};
 r.onsuccess=()=>{const d=r.result;d.onversionchange=()=>d.close();res(d)};r.onerror=()=>rej(r.error||new Error('indexedDB'));r.onblocked=()=>rej(Object.assign(new Error('indexedDB blocked'),{code:'unavailable'}))})}
const idbErr=e=>{const n=e&&e.name;if(n==='QuotaExceededError')return Object.assign(new Error(e.message||n),{code:'quota_exceeded'});return e||new Error('indexedDB')};
function idbTx(db,mode,fn){return new Promise((res,rej)=>{let out,tx;try{tx=db.transaction(IDB_STORE,mode,mode==='readwrite'?{durability:'strict'}:undefined)}catch(e){rej(idbErr(e));return}
 const st=tx.objectStore(IDB_STORE);try{fn(st,v=>{out=v})}catch(e){try{tx.abort()}catch(z){}rej(idbErr(e));return}
 tx.oncomplete=()=>res(out);tx.onerror=()=>rej(idbErr(tx.error));tx.onabort=()=>rej(idbErr(tx.error||new Error('aborted')))})}
const idbSnap=(p,v)=>({id:p.split('/').pop(),exists:v!==undefined,data:()=>v===undefined?undefined:JSON.parse(JSON.stringify(v)),metadata:{fromCache:false,hasPendingWrites:false}});
function idbStore(db){
 const doc=p=>({id:p.split('/').pop(),path:p,
  get:()=>idbTx(db,'readonly',(st,out)=>{const r=st.get(p);r.onsuccess=()=>out(idbSnap(p,r.result))}),
  set:d=>idbTx(db,'readwrite',st=>{st.put(JSON.parse(JSON.stringify(d)),p)}),
  delete:()=>idbTx(db,'readwrite',st=>{st.delete(p)}),
  collection:c=>col(p+'/'+c)});
 const col=p=>({path:p,doc:id=>doc(p+'/'+id),
  get:()=>idbTx(db,'readonly',(st,out)=>{const rng=IDBKeyRange.bound(p+'/',p+'/￿'),kr=st.getAllKeys(rng),vr=st.getAll(rng);
   vr.onsuccess=()=>{const ks=kr.result||[],vs=vr.result||[],docs=[];for(let i=0;i<ks.length;i++){const k=String(ks[i]);if(k.slice(p.length+1).indexOf('/')<0)docs.push(idbSnap(k,vs[i]))}out({docs,size:docs.length,empty:!docs.length,metadata:{fromCache:false}})}})});
 return{doc,collection:col}}

/* ================= платформа: артефакт Claude или самостоятельная PWA =================
   KURS_PLATFORM задаётся сборкой: 'pwa' в index.html PWA, иначе — артефакт.
   в PWA нет ни одного обращения к window.claude: хранилище — IndexedDB, файлы — через системное «поделиться»/скачивание. */
const PLATFORM=(typeof window!=='undefined'&&window.KURS_PLATFORM)==='pwa'?'pwa':'claude';
const isPWA=PLATFORM==='pwa';
async function openStore(){
 if(isPWA){if(!('indexedDB' in window)||!window.indexedDB)throw Object.assign(new Error(t('pwa.noIdb')),{code:'unavailable'});
  const db=await idbOpen();UI.persist=null;
  try{if(navigator.storage&&navigator.storage.persist){UI.persist=await navigator.storage.persisted()||await navigator.storage.persist()}}catch(e){}
  return{db:idbStore(db),uid:'local'}}
 const db=await claude.use('db'),user=await claude.use('user');if(!db||!user)throw new Error(t('err.noDb'));const uid=await user.id();if(!uid)throw new Error(t('err.noUid'));return{db,uid}}
/* сохранить файл у пользователя. артефакт — возможность downloads; PWA — подготовленный файл и отдельная кнопка,
   потому что iOS разрешает «поделиться» только прямо по нажатию. возвращает: 'shared' (передан в «поделиться»), 'downloaded' (скачивание запущено), 'cancelled', 'error'.
   ни один из этих ответов не означает, что файл точно лёг в нужную папку — это подтверждает только пользователь */
async function saveFile(name,blob){
 if(!isPWA){let dl=null;try{dl=await claude.use('downloads')}catch(e){}if(!dl)throw{code:'unavailable'};await dl.save({filename:name,data:blob});return'downloaded'}
 return new Promise(res=>{UI.fileR=res;UI.fileB={name,blob};
  sheet(`<div class="hdl"></div><div class="sh"><div><h2 style="font-size:24px">${t('pwa.fileReady')}</h2><div class="m" style="font-size:14px;overflow-wrap:anywhere">${esc(name)} · ${fnum(blob.size/1048576,1)} ${t('pwa.mb')}</div></div></div>
  <div class="t2" style="margin:10px 2px 14px;font-size:15px">${t('pwa.fileHint')}</div>
  <button class="btn pri blk" data-act="fileGo">${t('pwa.fileSave')}</button><button class="btn blk" style="margin:10px 0 calc(18px + env(safe-area-inset-bottom,0px))" data-act="fileNo">${t('common.cancel')}</button>`,'ov2')})}
async function fileGo(){const f=UI.fileB;if(!f)return;const file=new File([f.blob],f.name,{type:f.blob.type||'application/octet-stream'});let r;
 try{if(navigator.canShare&&navigator.canShare({files:[file]})){await navigator.share({files:[file]});r='shared'}
  else{const u=URL.createObjectURL(f.blob),a=document.createElement('a');a.href=u;a.download=f.name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(u),60000);r='downloaded'}}
 catch(e){r=e&&e.name==='AbortError'?'cancelled':'error'}
 fileDone(r)}
function fileDone(r){closeSheet('ov2');const res=UI.fileR;UI.fileR=null;UI.fileB=null;res&&res(r)}
const fileOk=r=>r==='shared'||r==='downloaded';
